function buildSkillConfig(kind) {
  const def = SKILL_DEFS[kind];
  return {
    version: "0.1",
    kind: "skill",
    id: def.id,
    name: def.name,
    description: def.description,
    triggerMode: "explicit",
    toolNames: def.toolNames,
    promptPatch: def.promptPatch,
    discover: { keywords: def.keywords }
  };
}
function buildBuiltinObjectSkillDbKey(kind, userId) {
  return createKey("page" /* DOC */, userId, BUILTIN_OBJECT_SKILL_IDS[kind]);
}
function buildBuiltinObjectSkillReference(kind, userId) {
  return {
    dbKey: buildBuiltinObjectSkillDbKey(kind, userId),
    title: SKILL_DEFS[kind].name,
    type: "instruction"
  };
}
function buildBuiltinObjectSkillPageContent(kind) {
  const def = SKILL_DEFS[kind];
  return buildSkillDocMarkdown({
    body: `# ${def.name}

${def.description}`,
    skillConfig: buildSkillConfig(kind)
  });
}
function ensureBuiltinObjectSkills(userId) {
  return async (dispatch) => {
    const { readAndWait, write } = await import("/public/assets/chunks/dbSlice-KCSAFONH.js");
    const now = Date.now();
    const skills = Object.keys(SKILL_DEFS).map(
      (kind) => ({
        kind,
        dbKey: buildBuiltinObjectSkillDbKey(kind, userId),
        title: SKILL_DEFS[kind].name,
        content: buildBuiltinObjectSkillPageContent(kind)
      })
    );
    for (const skill of skills) {
      try {
        const existing = await dispatch(readAndWait(skill.dbKey)).unwrap().catch(() => null);
        if (!existing) {
          await dispatch(
            write({
              data: {
                id: BUILTIN_OBJECT_SKILL_IDS[skill.kind],
                dbKey: skill.dbKey,
                type: "page" /* DOC */,
                userId,
                title: skill.title,
                content: skill.content,
                created: new Date(now).toISOString(),
                createdAt: now,
                updatedAt: String(now)
              },
              customKey: skill.dbKey
            })
          ).unwrap();
        }
      } catch {
      }
    }
  };
}

